"""The lattice generated by the exact semigroup of clean bridges: the Z-span of (h3, h8, h11, g; M = N + 3) over the clean
bridges with 3..11 beads, by integer row reduction (own code; lattice helpers of the harness)."""
import sys, importlib.util
from math import gcd
sys.argv = ['x']
import os
spec = importlib.util.spec_from_file_location("harness", os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "falsify_conjectures.py"))
H = importlib.util.module_from_spec(spec); sys.dont_write_bytecode = True; spec.loader.exec_module(H)
z3 = H.ls_enum(3, bridge=True)[0]
diff = lambda a, b: tuple(a[k] - b[k] for k in range(4))
def clean(w):
    if w[-2][1] - w[-3][1] != 1:
        return False
    top, _, _ = H.ls_concat(w, z3, 0); bot, _, _ = H.ls_concat(z3, w, 0)
    return diff(H.ls_profile(top), H.ls_profile(w)) == (0,0,0,0) and diff(H.ls_profile(bot), H.ls_profile(w)) == (0,0,0,0)
def hnf(rows):
    """integer row echelon form of a set of integer vectors (basis of their Z-span)"""
    rows = [list(r) for r in rows]
    basis = []
    ncol = len(rows[0])
    for col in range(ncol):
        piv = [r for r in rows if r[col] != 0]
        rest = [r for r in rows if r[col] == 0]
        while len(piv) > 1:
            piv.sort(key=lambda r: abs(r[col]))
            p = piv[0]
            new = [p]
            for r in piv[1:]:
                q = r[col] // p[col]
                r2 = [a - q * b for a, b in zip(r, p)]
                (new if r2[col] != 0 else rest).append(r2)
            piv = new
        if piv:
            basis.append(piv[0])
        rows = [r for r in rest if any(r)]
        if not rows:
            break
    return basis
vecs = set()
for N in range(3, 12):
    for w in H.ls_enum(N, bridge=True):
        if clean(w):
            vecs.add(tuple(H.ls_profile(w)) + (N + 3,))
    B = hnf(sorted(vecs))
    det = 1
    for i, r in enumerate(B):
        det *= abs(r[[j for j in range(5) if r[j] != 0][0]])
    print(f"clean bridges with at most {N} beads: {len(vecs)} distinct vectors (h3, h8, h11, g; M); rank {len(B)}; "
          f"index of their span in Z^5 {'%d' % det if len(B) == 5 else '(not of full rank)'}; basis {B}")
